using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------
var builder = Host.CreateApplicationBuilder(args);
builder.Logging.SetMinimumLevel(LogLevel.Warning);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? builder.Configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? builder.Configuration["AI:Model"]
    ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

// ---------------------------------------------------------------------------
// Resolve services & build the agent
// ---------------------------------------------------------------------------
var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic the user gives you.

        Workflow:
        1. Break the topic into 2-3 focused search queries.
        2. Use the WebSearch tool for each query.
        3. Use the SaveNote tool to record key findings (include the source URL).
        4. After gathering enough information, use GetNotes to review everything.
        5. Provide a concise, well-structured summary with source references.

        Always cite sources. Be thorough but concise.
        """,
};

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    RetainToolMessages = true,
    Tools = [AIFunctionFactory.Create(tools.WebSearch),
             AIFunctionFactory.Create(tools.SaveNote),
             AIFunctionFactory.Create(tools.GetNotes)],
    Temperature = 0f,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
return;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? throw new InvalidOperationException("A research topic is required.")
        : topic;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

/// <summary>Simple in-memory notepad for the agent to record findings.</summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];
    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> Notes => _notes;
}

/// <summary>Tools exposed to the research agent.</summary>
sealed class ResearchTools(Notepad notepad)
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a summary of results. Use this to find information about a topic.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");

        try
        {
            // Use DuckDuckGo HTML search (no API key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseSearchResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings with their source URL.")]
    public string SaveNote(
        [Description("The note text to save, including source attribution")] string note)
    {
        notepad.Add(note);
        Console.WriteLine($"  📝 Note saved ({notepad.Notes.Count} total)");
        return $"Note saved. You now have {notepad.Notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes. Use this before writing the final summary.")]
    public string GetNotes()
    {
        if (notepad.Notes.Count == 0)
            return "No notes saved yet.";

        var formatted = notepad.Notes
            .Select((n, i) => $"[{i + 1}] {n}");
        return string.Join("\n\n", formatted);
    }

    /// <summary>Extracts result snippets from DuckDuckGo HTML response.</summary>
    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        var snippetTag = "class=\"result__snippet\"";
        var titleTag = "class=\"result__a\"";

        var pos = 0;
        while (results.Count < 5)
        {
            // Find title
            var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
            if (titleStart < 0) break;

            var titleTextStart = html.IndexOf('>', titleStart + titleTag.Length);
            if (titleTextStart < 0) break;
            titleTextStart++;

            var titleTextEnd = html.IndexOf('<', titleTextStart);
            if (titleTextEnd < 0) break;

            var title = WebUtility.HtmlDecode(html[titleTextStart..titleTextEnd]).Trim();

            // Find href for URL
            var hrefSearch = html.LastIndexOf("href=\"", titleStart, titleStart - Math.Max(0, titleStart - 500), StringComparison.Ordinal);
            var resultUrl = "";
            if (hrefSearch >= 0)
            {
                var hrefStart = hrefSearch + 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                {
                    resultUrl = WebUtility.HtmlDecode(html[hrefStart..hrefEnd]);
                    // DuckDuckGo wraps URLs in a redirect; extract the actual URL
                    var uddgIndex = resultUrl.IndexOf("uddg=", StringComparison.Ordinal);
                    if (uddgIndex >= 0)
                        resultUrl = WebUtility.UrlDecode(resultUrl[(uddgIndex + 5)..]);
                }
            }

            // Find snippet
            var snippetStart = html.IndexOf(snippetTag, titleTextEnd, StringComparison.Ordinal);
            var snippet = "";
            if (snippetStart >= 0)
            {
                var snippetTextStart = html.IndexOf('>', snippetStart + snippetTag.Length);
                if (snippetTextStart >= 0)
                {
                    snippetTextStart++;
                    var snippetTextEnd = html.IndexOf("</a>", snippetTextStart, StringComparison.Ordinal);
                    if (snippetTextEnd < 0)
                        snippetTextEnd = html.IndexOf("</td>", snippetTextStart, StringComparison.Ordinal);
                    if (snippetTextEnd >= 0)
                    {
                        snippet = StripHtml(html[snippetTextStart..snippetTextEnd]).Trim();
                    }
                }
                pos = snippetStart + 1;
            }
            else
            {
                pos = titleTextEnd + 1;
            }

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title, snippet, resultUrl));
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var output = new System.Text.StringBuilder(html.Length);
        var inTag = false;
        foreach (var ch in html)
        {
            if (ch == '<') { inTag = true; continue; }
            if (ch == '>') { inTag = false; continue; }
            if (!inTag) output.Append(ch);
        }
        return WebUtility.HtmlDecode(output.ToString());
    }
}

record SearchResult(string Title, string Snippet, string Url);

