using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------
var builder = Host.CreateApplicationBuilder(args);
builder.Logging.SetMinimumLevel(LogLevel.Warning);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? builder.Configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? builder.Configuration["AI:Model"]
    ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

// ---------------------------------------------------------------------------
// Resolve services & build the agent
// ---------------------------------------------------------------------------
var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic the user gives you.

        Workflow:
        1. Break the topic into 2-3 focused search queries.
        2. Use the WebSearch tool for each query.
        3. Use the SaveNote tool to record key findings (include the source URL).
        4. After gathering enough information, use GetNotes to review everything.
        5. Provide a concise, well-structured summary with source references.

        Always cite sources. Be thorough but concise.
        """,
};

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    RetainToolMessages = true,
    Tools = [AIFunctionFactory.Create(tools.WebSearch),
             AIFunctionFactory.Create(tools.SaveNote),
             AIFunctionFactory.Create(tools.GetNotes)],
    Temperature = 0f,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
return;

