using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Build tools and agent
// ---------------------------------------------------------------------------
var notepad = new Notepad();
var tools = new ResearchTools(notepad);

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic the user gives you.

        Workflow:
        1. Break the topic into 2-3 focused search queries.
        2. Use the WebSearch tool for each query.
        3. Use the SaveNote tool to record key findings (include the source URL).
        4. After gathering enough information, use GetNotes to review everything.
        5. Provide a concise, well-structured summary with source references.

        Always cite sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    tools:
    [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
})
{
    MaxIterations = 15,
};

await foreach (var update in agent.RunStreamingAsync(messages, runOptions: runOptions))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();
return;

