160.     /// <summary>Extracts result snippets from DuckDuckGo HTML response.</summary>
161.     private static List<SearchResult> ParseSearchResults(string html)
162.     {
163.         var results = new List<SearchResult>();
164.         var snippetTag = "class=\"result__snippet\"";
165.         var titleTag = "class=\"result__a\"";
166. 
167.         var pos = 0;
168.         while (results.Count < 5)
169.         {
170.             // Find title
171.             var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
172.             if (titleStart < 0) break;
173. 
174.             var titleTextStart = html.IndexOf('>', titleStart + titleTag.Length);
175.             if (titleTextStart < 0) break;
176.             titleTextStart++;
177. 
178.             var titleTextEnd = html.IndexOf('<', titleTextStart);
179.             if (titleTextEnd < 0) break;
180. 
181.             var title = WebUtility.HtmlDecode(html[titleTextStart..titleTextEnd]).Trim();
182. 
183.             // Find href for URL
184.             var hrefSearch = html.LastIndexOf("href=\"", titleStart, titleStart - Math.Max(0, titleStart - 500), StringComparison.Ordinal);
185.             var resultUrl = "";
186.             if (hrefSearch >= 0)
187.             {
188.                 var hrefStart = hrefSearch + 6;
189.                 var hrefEnd = html.IndexOf('"', hrefStart);
190.                 if (hrefEnd > hrefStart)
191.                 {
192.                     resultUrl = WebUtility.HtmlDecode(html[hrefStart..hrefEnd]);
193.                     // DuckDuckGo wraps URLs in a redirect; extract the actual URL
194.                     var uddgIndex = resultUrl.IndexOf("uddg=", StringComparison.Ordinal);
195.                     if (uddgIndex >= 0)
196.                         resultUrl = WebUtility.UrlDecode(resultUrl[(uddgIndex + 5)..]);
197.                 }
198.             }
199. 
200.             // Find snippet
201.             var snippetStart = html.IndexOf(snippetTag, titleTextEnd, StringComparison.Ordinal);
202.             var snippet = "";
203.             if (snippetStart >= 0)
204.             {
205.                 var snippetTextStart = html.IndexOf('>', snippetStart + snippetTag.Length);
206.                 if (snippetTextStart >= 0)
207.                 {
208.                     snippetTextStart++;
209.                     var snippetTextEnd = html.IndexOf("</a>", snippetTextStart, StringComparison.Ordinal);
210.                     if (snippetTextEnd < 0)
211.                         snippetTextEnd = html.IndexOf("</td>", snippetTextStart, StringComparison.Ordinal);
212.                     if (snippetTextEnd >= 0)
213.                     {
214.                         snippet = StripHtml(html[snippetTextStart..snippetTextEnd]).Trim();
215.                     }
216.                 }
217.                 pos = snippetStart + 1;
218.             }
219.             else
220.             {
221.                 pos = titleTextEnd + 1;
222.             }
223. 
224.             if (!string.IsNullOrWhiteSpace(title))
225.                 results.Add(new SearchResult(title, snippet, resultUrl));
226.         }
227. 
228.         return results;
229.     }
