231.     private static string StripHtml(string html)
232.     {
233.         var output = new System.Text.StringBuilder(html.Length);
234.         var inTag = false;
235.         foreach (var ch in html)
236.         {
237.             if (ch == '<') { inTag = true; continue; }
238.             if (ch == '>') { inTag = false; continue; }
239.             if (!inTag) output.Append(ch);
240.         }
241.         return WebUtility.HtmlDecode(output.ToString());
242.     }
243. }
